types.text:
interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};

type TabsOwnProps = {
  items?: MuxUIItems;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  orientation?: 'horizontal' | 'vertical';
  keyboardActivation?: 'automatic' | 'manual';
  size?: ControlSize;
  variant?: 'underline' | 'pill' | 'overflow' | 'segment';
  onChange?: (value: string) => void;
};

type TabsProps = TabsOwnProps & {
  className?: string;
} & MuxUIAriaAccessibleName;
